void SOC_LIFECYCLEProxy<_AttributeExtensions...>::Update_Emergency_Call_status(::iMicro::iMicroTypes::call_status_enum _status, CommonAPI::CallStatus &_internalCallStatus, const CommonAPI::CallInfo *_info) {
    if (!_status.validate()) {
        _internalCallStatus = CommonAPI::CallStatus::INVALID_VALUE;
        return;
    }
    delegate_->Update_Emergency_Call_status(_status, _internalCallStatus, _info);
}

template <typename ... _AttributeExtensions>
std::future<CommonAPI::CallStatus> SOC_LIFECYCLEProxy<_AttributeExtensions...>::Update_Emergency_Call_statusAsync(const ::iMicro::iMicroTypes::call_status_enum &_status, Update_Emergency_Call_statusAsyncCallback _callback, const CommonAPI::CallInfo *_info) {
    if (!_status.validate()) {
        _callback(CommonAPI::CallStatus::INVALID_VALUE);
        std::promise<CommonAPI::CallStatus> promise;
        promise.set_value(CommonAPI::CallStatus::INVALID_VALUE);
        return promise.get_future();
    }
    return delegate_->Update_Emergency_Call_statusAsync(_status, _callback, _info);
}
